using AutoApprover.Worker.Services;
using OpenTelemetry.Metrics;
using OpenTelemetry.Trace;

var builder = Host.CreateApplicationBuilder(args);

// Konfiguration
builder.Configuration.AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
                   .AddJsonFile($"appsettings.{builder.Environment.EnvironmentName}.json", optional: true, reloadOnChange: true)
                   .AddEnvironmentVariables();

// Worker-Dienst
builder.Services.AddHostedService<Worker>();

// HTTP-Client für Azure DevOps REST-API
builder.Services.AddHttpClient<IAdoApiClient, AdoApiClient>((sp, client) =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    client.BaseAddress = new Uri(config["AdopSettings:OrganizationUrl"]!);
    client.DefaultRequestHeaders.Accept.Add(new("application/json"));
    var pat = config["AdopSettings:Pat"] ?? Environment.GetEnvironmentVariable("ADO_PAT") ?? string.Empty;
    if (!string.IsNullOrEmpty(pat))
    {
        // Basic Auth mit PAT: Benutzername ist leer, Passwort ist der PAT
        var convert = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes($":{pat}"));
        client.DefaultRequestHeaders.Authorization = new("Basic", convert);
    }
});

// PostgreSQL Audit-Repository
builder.Services.AddSingleton<IAuditRepository, AuditRepository>(sp =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    var connString = config.GetConnectionString("AutoApproveDb")
                     ?? Environment.GetEnvironmentVariable("DB_CONNECTION_STRING")
                     ?? throw new InvalidOperationException("Connection string 'AutoApproveDb' oder Umgebungsvariable DB_CONNECTION_STRING nicht gefunden.");
    return new AuditRepository(connString);
});

// Decision Engine
builder.Services.AddSingleton<IDecisionEngine, DecisionEngine>();

// Teams Benachrichtigung
builder.Services.AddSingleton<ITeamsNotifier, TeamsNotifier>(sp =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    var webhookUrl = config["Teams:WebhookUrl"] ?? Environment.GetEnvironmentVariable("TEAMS_WEBHOOK_URL") ?? string.Empty;
    return new TeamsNotifier(webhookUrl);
});

// OpenTelemetry: Traces, Metriken, Logs
builder.Services.AddOpenTelemetry()
    .WithTracing(tracing => tracing
        .AddSource("AutoApprover.Worker")
        .AddHttpClientInstrumentation()
        .AddConsoleExporter()
        .AddOtlpExporter(o => o.Endpoint = new Uri(builder.Configuration["Otlp:Endpoint"] ?? "http://localhost:4317")))
    .WithMetrics(metrics => metrics
        .AddMeter("AutoApprover.Worker")
        .AddConsoleExporter()
        .AddOtlpExporter(o => o.Endpoint = new Uri(builder.Configuration["Otlp:Endpoint"] ?? "http://localhost:4317")));

builder.Logging.AddOpenTelemetry(options =>
{
    options.IncludeScopes = true;
    options.OtlpEndpoint = new Uri(builder.Configuration["Otlp:Endpoint"] ?? "http://localhost:4317");
});

var app = builder.Build();

// Datenbank initialisieren (Tabellen anlegen, falls nicht vorhanden)
using (var scope = app.Services.CreateScope())
{
    var auditRepo = scope.ServiceProvider.GetRequiredService<IAuditRepository>();
    await auditRepo.EnsureSchemaAsync();
}

await app.RunAsync();

using AutoApprover.Worker.Models;
using AutoApprover.Worker.Services;

namespace AutoApprover.Worker;

public sealed class Worker(
    IAdoApiClient adoApiClient,
    IDecisionEngine decisionEngine,
    IAuditRepository auditRepository,
    ITeamsNotifier teamsNotifier,
    IConfiguration configuration,
    ILogger<Worker> logger) : BackgroundService
{
    private readonly TimeSpan _pollingInterval = TimeSpan.FromSeconds(
        configuration.GetValue<int>("AdopSettings:PollingIntervalSeconds", 60));

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        logger.LogInformation("Auto-Approver Worker gestartet. Polling-Intervall: {Interval}s", _pollingInterval.TotalSeconds);

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                await ProcessPendingChecksAsync(stoppingToken);
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Unerwarteter Fehler im Polling-Zyklus");
            }

            await Task.Delay(_pollingInterval, stoppingToken);
        }

        logger.LogInformation("Auto-Approver Worker beendet.");
    }

    private async Task ProcessPendingChecksAsync(CancellationToken ct)
    {
        logger.LogDebug("Prüfe auf ausstehende Environment-Checks ...");

        var pendingChecks = await adoApiClient.GetPendingChecksAsync(ct);
        logger.LogInformation("{Count} ausstehende Check-Evaluations gefunden", pendingChecks.Count);

        foreach (var check in pendingChecks)
        {
            if (ct.IsCancellationRequested)
                break;

            try
            {
                await ProcessCheckAsync(check, ct);
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Fehler bei der Verarbeitung von CheckEvaluation {CheckEvaluationId} in Environment {Environment}", check.Id, check.EnvironmentName);
            }
        }
    }

    private async Task ProcessCheckAsync(PendingCheck check, CancellationToken ct)
    {
        logger.LogInformation("Verarbeite CheckEvaluation {Id} (Environment: {Environment}, Pipeline: {Pipeline})",
            check.Id, check.EnvironmentName, check.PipelineName);

        // 1. PR / Commit auflösen, um den Ersteller und die geänderten Dateien zu prüfen
        var prInfo = await adoApiClient.GetPullRequestForCommitAsync(
            check.ProjectName,
            check.RepositoryId,
            check.SourceCommitId,
            ct);

        // 2. Entscheidung treffen
        var decision = decisionEngine.Evaluate(check, prInfo);

        // 3. Ausführen oder überspringen
        if (decision.ShouldApprove)
        {
            await adoApiClient.ApproveCheckAsync(check.Id, ct);
            logger.LogInformation("CheckEvaluation {Id} automatisch genehmigt. Grund: {Reason}", check.Id, decision.Reason);
        }
        else
        {
            logger.LogInformation("CheckEvaluation {Id} übersprungen. Grund: {Reason}", check.Id, decision.Reason);
        }

        // 4. Audit-Log in PostgreSQL
        await auditRepository.WriteAsync(decision with
        {
            RunId = check.RunId,
            CommitId = check.SourceCommitId,
            EnvironmentName = check.EnvironmentName,
            ProjectName = check.ProjectName,
            PipelineName = check.PipelineName,
            Decision = decision.ShouldApprove ? "approved" : "skipped",
            Reason = decision.Reason,
            ApprovedAt = decision.ShouldApprove ? DateTimeOffset.UtcNow : null
        }, ct);

        // 5. Teams-Benachrichtigung
        await teamsNotifier.NotifyAsync(decision);
    }
}

namespace AutoApprover.Worker.Models;

public sealed record DecisionResult(
    bool ShouldApprove,
    string Reason,
    string ChangeType, // "dockerfile_digest", "patch", "minor", "none"
    int PullRequestId,
    string? PullRequestTitle = null,
    string? PullRequestCreator = null)
{
    public DecisionResult with
    {
        int? RunId = null,
        string? CommitId = null,
        string? EnvironmentName = null,
        string? ProjectName = null,
        string? PipelineName = null,
        string? Decision = null,
        DateTimeOffset? ApprovedAt = null
    } => this;
}

using AutoApprover.Worker.Models;

namespace AutoApprover.Worker.Services;

public interface IAdoApiClient
{
    /// <summary>
    /// Liefert alle ausstehende (pending) Check-Evaluations für Environments.
    /// </summary>
    Task<IReadOnlyList<PendingCheck>> GetPendingChecksAsync(CancellationToken ct = default);

    /// <summary>
    /// Löst den zugehörigen Pull-Request für einen Commit auf, inkl. geänderter Dateien.
    /// </summary>
    Task<PullRequestInfo?> GetPullRequestForCommitAsync(
        string projectName,
        string repositoryId,
        string commitId,
        CancellationToken ct = default);

    /// <summary>
    /// Genehmigt eine Check-Evaluation per PATCH (Bypass-Approvals).
    /// </summary>
    Task ApproveCheckAsync(int checkEvaluationId, CancellationToken ct = default);
}

using System.Text.Json;
using AutoApprover.Worker.Models;

namespace AutoApprover.Worker.Services;

public sealed class AdoApiClient(HttpClient httpClient, ILogger<AdoApiClient> logger) : IAdoApiClient
{
    private const string ApiVersion = "7.2-preview.1";
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

    public async Task<IReadOnlyList<PendingCheck>> GetPendingChecksAsync(CancellationToken ct = default)
    {
        // CHECKS-API: Liste aller Check-Evaluations mit Status 'pending'
        // Endpoint variiert je nach ADO Server Version; hier der typische Pfad für Azure DevOps Server 2022.x:
        var url = $"_apis/pipelines/checks/check-evaluations?api-version={ApiVersion}&statusFilter=pending";

        using var response = await httpClient.GetAsync(url, ct);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(ct);
        var doc = JsonDocument.Parse(json);

        var checks = new List<PendingCheck>();
        foreach (var element in doc.RootElement.EnumerateArray())
        {
            checks.Add(new PendingCheck(
                Id: element.GetProperty("id").GetInt32(),
                EnvironmentName: element.GetProperty("environment").GetProperty("name").GetString() ?? string.Empty,
                ProjectName: element.GetProperty("environment").GetProperty("project").GetProperty("name").GetString() ?? string.Empty,
                PipelineName: element.TryGetProperty("pipeline", out var p) ? p.GetProperty("name").GetString() ?? string.Empty : string.Empty,
                RunId: element.TryGetProperty("pipelineRun", out var r) && r.TryGetProperty("id", out var rid) ? rid.GetInt32() : 0,
                RepositoryId: element.TryGetProperty("resource", out var res) && res.TryGetProperty("repository", out var repo) && repo.TryGetProperty("id", out var rid2) ? rid2.GetString() ?? string.Empty : string.Empty,
                SourceCommitId: element.TryGetProperty("resource", out var res2) && res2.TryGetProperty("repository", out var repo2) && repo2.TryGetProperty("version", out var ver) ? ver.GetString() ?? string.Empty : string.Empty,
                SourceBranch: element.TryGetProperty("resource", out var res3) && res3.TryGetProperty("repository", out var repo3) && repo3.TryGetProperty("branch", out var br) ? br.GetString() : null,
                DefinitionName: element.TryGetProperty("definition", out var def) ? def.GetProperty("name").GetString() : null
            ));
        }

        return checks;
    }

    public async Task<PullRequestInfo?> GetPullRequestForCommitAsync(
        string projectName,
        string repositoryId,
        string commitId,
        CancellationToken ct = default)
    {
        // PRs suchen, die den Commit enthalten (lastMergeTargetCommit / lastMergeSourceCommit)
        var url = $"_apis/git/repositories/{repositoryId}/pullrequests?api-version={ApiVersion}&searchCriteria.status=active,completed&searchCriteria.repositoryId={repositoryId}";

        using var response = await httpClient.GetAsync(url, ct);
        if (!response.IsSuccessStatusCode)
        {
            logger.LogWarning("Konnte Pull-Requests nicht laden (Status {StatusCode})", response.StatusCode);
            return null;
        }

        var json = await response.Content.ReadAsStringAsync(ct);
        var doc = JsonDocument.Parse(json);

        foreach (var pr in doc.RootElement.GetProperty("value").EnumerateArray())
        {
            var prId = pr.GetProperty("pullRequestId").GetInt32();
            var title = pr.GetProperty("title").GetString() ?? string.Empty;
            var creator = pr.GetProperty("createdBy");
            var creatorDisplay = creator.TryGetProperty("displayName", out var dn) ? dn.GetString() ?? string.Empty : string.Empty;
            var creatorUnique = creator.TryGetProperty("uniqueName", out var un) ? un.GetString() ?? string.Empty : string.Empty;
            var sourceBranch = pr.GetProperty("sourceRefName").GetString() ?? string.Empty;
            var targetBranch = pr.GetProperty("targetRefName").GetString() ?? string.Empty;

            // Geänderte Dateien des PR abfragen
            var changedFiles = await GetChangedFilesAsync(repositoryId, prId, ct);

            // Prüfung: Enthält der PR den Ziel-Commit als Merge-Ziel?
            if (pr.TryGetProperty("lastMergeTargetCommit", out var targetCommit) &&
                targetCommit.TryGetProperty("commitId", out var tcid) &&
                tcid.GetString() == commitId)
            {
                return new PullRequestInfo(
                    Id: prId,
                    Title: title,
                    CreatorDisplayName: creatorDisplay,
                    CreatorUniqueName: creatorUnique,
                    SourceBranch: sourceBranch,
                    TargetBranch: targetBranch,
                    ChangedFilePaths: changedFiles);
            }
        }

        return null;
    }

    public Task ApproveCheckAsync(int checkEvaluationId, CancellationToken ct = default)
    {
        var url = $"_apis/pipelines/checks/check-evaluations/{checkEvaluationId}?api-version={ApiVersion}";
        var body = JsonSerializer.Serialize(new { status = "approved" }, JsonOptions);
        using var content = new StringContent(body, System.Text.Encoding.UTF8, "application/json");

        return httpClient.PatchAsync(url, content, ct).ContinueWith(async t =>
        {
            var resp = await t;
            resp.EnsureSuccessStatusCode();
            logger.LogInformation("CheckEvaluation {Id} erfolgreich genehmigt (Status {StatusCode})", checkEvaluationId, resp.StatusCode);
        }, ct);
    }

    private async Task<IReadOnlyList<string>> GetChangedFilesAsync(string repositoryId, int pullRequestId, CancellationToken ct)
    {
        var url = $"_apis/git/repositories/{repositoryId}/pullrequests/{pullRequestId}/diffs/commits?api-version={ApiVersion}";

        using var response = await httpClient.GetAsync(url, ct);
        if (!response.IsSuccessStatusCode)
            return Array.Empty<string>();

        var json = await response.Content.ReadAsStringAsync(ct);
        var doc = JsonDocument.Parse(json);

        var files = new List<string>();
        foreach (var change in doc.RootElement.GetProperty("changes").EnumerateArray())
        {
            if (change.TryGetProperty("item", out var item) && item.TryGetProperty("path", out var path))
                files.Add(path.GetString() ?? string.Empty);
        }

        return files;
    }
}

using AutoApprover.Worker.Models;

namespace AutoApprover.Worker.Services;

public interface IDecisionEngine
{
    /// <summary>
    /// Bewertet, ob eine Check-Evaluation automatisch genehmigt werden darf.
    /// </summary>
    DecisionResult Evaluate(PendingCheck check, PullRequestInfo? prInfo);
}

using AutoApprover.Worker.Models;

namespace AutoApprover.Worker.Services;

public sealed class DecisionEngine(
    IConfiguration configuration,
    ILogger<DecisionEngine> logger) : IDecisionEngine
{
    private readonly string _renovateCreator = configuration["AdopSettings:RenovatePrCreator"] ?? "renovate";

    public DecisionResult Evaluate(PendingCheck check, PullRequestInfo? prInfo)
    {
        // Kein PR gefunden -> nicht automatisch genehmigen
        if (prInfo is null)
            return new DecisionResult(false, "Kein zugehöriger Pull-Request gefunden", "none", 0);

        // 1. PR-Ersteller prüfen (nicht nur Titel!)
        if (!string.Equals(prInfo.CreatorDisplayName, _renovateCreator, StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(prInfo.CreatorUniqueName, _renovateCreator, StringComparison.OrdinalIgnoreCase))
        {
            return new DecisionResult(
                false,
                $"PR-Ersteller '{prInfo.CreatorDisplayName}' ist nicht der konfigurierte Renovate-Bot ('{_renovateCreator}')",
                "none",
                prInfo.Id,
                prInfo.Title,
                prInfo.CreatorDisplayName);
        }

        // 2. Geänderte Dateien prüfen
        var fileAnalysis = AnalyzeChangedFiles(prInfo.ChangedFilePaths);
        if (!fileAnalysis.IsAllowed)
            return new DecisionResult(
                false,
                $"Nicht erlaubte Dateien im PR: {string.Join(", ", fileAnalysis.DisallowedFiles)}",
                "none",
                prInfo.Id,
                prInfo.Title,
                prInfo.CreatorDisplayName);

        // 3. Semver: Kein Major-Upgrade (prüfe Titel und Dateinamen)
        if (IsMajorUpgrade(prInfo.Title, prInfo.ChangedFilePaths))
            return new DecisionResult(
                false,
                "Major-Upgrade erkannt (nicht automatisch genehmigbar)",
                "none",
                prInfo.Id,
                prInfo.Title,
                prInfo.CreatorDisplayName);

        // 4. Entscheidung positiv
        var changeType = fileAnalysis.ChangeType;
        return new DecisionResult(
            true,
            $"Auto-Approved: PR-Ersteller={prInfo.CreatorDisplayName}, Änderungstyp={changeType}, Dateien={string.Join(", ", prInfo.ChangedFilePaths)}",
            changeType,
            prInfo.Id,
            prInfo.Title,
            prInfo.CreatorDisplayName);
    }

    private static FileAnalysis AnalyzeChangedFiles(IReadOnlyList<string> changedFiles)
    {
        var disallowed = new List<string>();
        var dockerfileChanges = new List<string>();
        var versionFileChanges = new List<string>();

        foreach (var file in changedFiles)
        {
            var lower = file.ToLowerInvariant();

            if (IsDockerfile(lower))
            {
                dockerfileChanges.Add(file);
            }
            else if (IsVersionFile(lower))
            {
                versionFileChanges.Add(file);
            }
            else
            {
                disallowed.Add(file);
            }
        }

        if (disallowed.Count > 0)
            return new FileAnalysis(false, "none", disallowed);

        // Nur Dockerfile-Änderungen: Prüfung auf SHA256-Digest oder Minor/Patch
        if (dockerfileChanges.Count > 0 && versionFileChanges.Count == 0)
        {
            // Vereinfachte Prüfung: Der Aufrufer (AdoApiClient) liefert nur die Pfade.
            // Die tatsächliche Digest-Prüfung müsste über den Diff-Inhalt erfolgen.
            // Hier markieren wir es als dockerfile_digest; die Detailprüfung erfolgt im AdoApiClient oder hier über den Diff-Inhalt.
            return new FileAnalysis(true, "dockerfile_digest", Array.Empty<string>());
        }

        // Nur Versionsdateien: als patch/minor behandeln
        if (versionFileChanges.Count > 0 && dockerfileChanges.Count == 0)
            return new FileAnalysis(true, "patch", Array.Empty<string>());

        // Gemischt oder leer
        return changedFiles.Count == 0
            ? new FileAnalysis(false, "none", Array.Empty<string>())
            : new FileAnalysis(true, "patch", Array.Empty<string>());
    }

    private static bool IsMajorUpgrade(string title, IReadOnlyList<string> files)
    {
        var lowerTitle = title.ToLowerInvariant();
        if (lowerTitle.Contains("major") || lowerTitle.Contains("breaking"))
            return true;

        foreach (var file in files)
        {
            var lower = file.ToLowerInvariant();
            if (lower.Contains("major") || lower.Contains("breaking"))
                return true;
        }

        return false;
    }

    private static bool IsDockerfile(string lowerPath) =>
        lowerPath.EndsWith("dockerfile") ||
        lowerPath.EndsWith(".dockerfile") ||
        lowerPath.Contains("dockerfile.");

    private static bool IsVersionFile(string lowerPath) =>
        lowerPath.EndsWith("csproj") ||
        lowerPath.EndsWith("nuspec") ||
        lowerPath.EndsWith("version.json") ||
        lowerPath.EndsWith("assemblyinfo.cs");

    private sealed record FileAnalysis(bool IsAllowed, string ChangeType, IReadOnlyList<string> DisallowedFiles);
}

using AutoApprover.Worker.Models;

namespace AutoApprover.Worker.Services;

public interface IAuditRepository
{
    Task EnsureSchemaAsync();
    Task WriteAsync(DecisionResult decision, CancellationToken ct = default);
}

using System.Text.Json;
using AutoApprover.Worker.Models;
using Npgsql;

namespace AutoApprover.Worker.Services;

public sealed class AuditRepository(string connectionString) : IAuditRepository
{
    public async Task EnsureSchemaAsync()
    {
        await using var conn = new NpgsqlConnection(connectionString);
        await conn.OpenAsync();

        var commands = new[]
        {
            """
            CREATE TABLE IF NOT EXISTS environment_auto_approve_config (
                id                   SERIAL PRIMARY KEY,
                environment_name     TEXT NOT NULL,
                project_name         TEXT NOT NULL,
                pipeline_id          TEXT,
                is_enabled           BOOLEAN DEFAULT TRUE,
                allowed_pr_creator   TEXT DEFAULT 'renovate',
                allowed_change_types TEXT[] DEFAULT ARRAY['dockerfile_digest','patch','minor'],
                created_at           TIMESTAMPTZ DEFAULT now(),
                updated_at           TIMESTAMPTZ DEFAULT now(),
                UNIQUE (environment_name, project_name)
            );
            """,
            """
            CREATE TABLE IF NOT EXISTS auto_approve_audit_log (
                id                BIGSERIAL PRIMARY KEY,
                environment_name  TEXT NOT NULL,
                project_name      TEXT NOT NULL,
                pipeline_name     TEXT,
                run_id            INTEGER,
                commit_id         TEXT,
                pr_id             INTEGER,
                pr_creator        TEXT,
                pr_title          TEXT,
                change_type       TEXT,
                decision          TEXT NOT NULL,
                reason            TEXT,
                approved_at       TIMESTAMPTZ,
                deployment_ok     BOOLEAN,
                created_at        TIMESTAMPTZ DEFAULT now()
            );
            """,
            """
            CREATE TABLE IF NOT EXISTS feature_flags (
                id          SERIAL PRIMARY KEY,
                name        TEXT UNIQUE NOT NULL,
                is_enabled  BOOLEAN DEFAULT FALSE,
                description TEXT,
                updated_at  TIMESTAMPTZ DEFAULT now()
            );
            """,
            """
            INSERT INTO feature_flags (name, is_enabled, description)
            VALUES ('auto_approve_global', TRUE, 'Hauptschalter für den Auto-Approver'),
                   ('auto_approve_production', TRUE, 'Auto-Approver auch in Produktion erlauben')
            ON CONFLICT (name) DO NOTHING;
            """
        };

        foreach (var cmd in commands)
        {
            await using var command = new NpgsqlCommand(cmd, conn);
            await command.ExecuteNonQueryAsync();
        }
    }

    public async Task WriteAsync(DecisionResult decision, CancellationToken ct = default)
    {
        await using var conn = new NpgsqlConnection(connectionString);
        await conn.OpenAsync();

        const string sql = """
            INSERT INTO auto_approve_audit_log
                (environment_name, project_name, pipeline_name, run_id, commit_id, pr_id, pr_creator, pr_title, change_type, decision, reason, approved_at)
            VALUES
                (@environmentName, @projectName, @pipelineName, @runId, @commitId, @prId, @prCreator, @prTitle, @changeType, @decision, @reason, @approvedAt);
        """;

        await using var cmd = new NpgsqlCommand(sql, conn);
        cmd.Parameters.AddWithValue("environmentName", decision.EnvironmentName ?? (object)DBNull.Value);
        cmd.Parameters.AddWithValue("projectName", decision.ProjectName ?? (object)DBNull.Value);
        cmd.Parameters.AddWithValue("pipelineName", decision.PipelineName ?? (object)DBNull.Value);
        cmd.Parameters.AddWithValue("runId", decision.RunId ?? (object)DBNull.Value);
        cmd.Parameters.AddWithValue("commitId", decision.CommitId ?? (object)DBNull.Value);
        cmd.Parameters.AddWithValue("prId", decision.PullRequestId == 0 ? (object)DBNull.Value : decision.PullRequestId);
        cmd.Parameters.AddWithValue("prCreator", decision.PullRequestCreator ?? (object)DBNull.Value);
        cmd.Parameters.AddWithValue("prTitle", decision.PullRequestTitle ?? (object)DBNull.Value);
        cmd.Parameters.AddWithValue("changeType", decision.ChangeType ?? (object)DBNull.Value);
        cmd.Parameters.AddWithValue("decision", decision.Decision ?? "skipped");
        cmd.Parameters.AddWithValue("reason", decision.Reason ?? (object)DBNull.Value);
        cmd.Parameters.AddWithValue("approvedAt", decision.ApprovedAt ?? (object)DBNull.Value);

        await cmd.ExecuteNonQueryAsync(ct);
    }
}

using AutoApprover.Worker.Models;

namespace AutoApprover.Worker.Services;

public interface ITeamsNotifier
{
    Task NotifyAsync(DecisionResult decision);
}

using System.Text.Json;
using AutoApprover.Worker.Models;

namespace AutoApprover.Worker.Services;

public sealed class TeamsNotifier(string webhookUrl) : ITeamsNotifier
{
    private static readonly HttpClient HttpClient = new();
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

    public async Task NotifyAsync(DecisionResult decision)
    {
        if (string.IsNullOrEmpty(webhookUrl))
            return;

        var color = decision.ShouldApprove ? "00FF00" : "FF0000";
        var title = decision.ShouldApprove ? "✅ Auto-Approver: Release genehmigt" : "⏭️ Auto-Approver: Release übersprungen";

        var card = new
        {
            type = "MessageCard",
            summary = title,
            themeColor = color,
            title = title,
            sections = new[]
            {
                new
                {
                    facts = new[]
                    {
                        new { name = "Entscheidung", value = decision.Decision },
                        new { name = "Grund", value = decision.Reason },
                        new { name = "Änderungstyp", value = decision.ChangeType },
                        new { name = "PR-ID", value = decision.PullRequestId == 0 ? "–" : decision.PullRequestId.ToString() },
                        new { name = "PR-Titel", value = decision.PullRequestTitle ?? "–" },
                        new { name = "PR-Ersteller", value = decision.PullRequestCreator ?? "–" },
                        new { name = "Umgebung", value = decision.EnvironmentName ?? "–" },
                        new { name = "Projekt", value = decision.ProjectName ?? "–" },
                        new { name = "Zeit", value = DateTimeOffset.UtcNow.ToString("yyyy-MM-dd HH:mm:ss UTC") }
                    }
                }
            }
        };

        var json = JsonSerializer.Serialize(card, JsonOptions);
        using var content = new StringContent(json, System.Text.Encoding.UTF8, "application/json");

        try
        {
            var response = await HttpClient.PostAsync(webhookUrl, content);
            response.EnsureSuccessStatusCode();
        }
        catch (Exception ex)
        {
            // Teams-Benachrichtigung darf den Worker nicht abstürzen lassen
            System.Console.WriteLine($"Fehler beim Senden der Teams-Nachricht: {ex.Message}");
        }
    }
}

