68:         var versionFileChanges = new List<string>();
69: 
70:         foreach (var file in changedFiles)
71:         {
72:             var lower = file.ToLowerInvariant();
73: 
74:             if (IsDockerfile(lower))
75:             {
76:                 dockerfileChanges.Add(file);
77:             }
78:             else if (IsVersionFile(lower))
79:             {
80:                 versionFileChanges.Add(file);
81:             }
82:             else
83:             {
84:                 disallowed.Add(file);
85:             }
86:         }
87: 
88:         if (disallowed.Count > 0)
89:             return new FileAnalysis(false, "none", disallowed);
90: 
91:         // Nur Dockerfile-Änderungen: Prüfung auf SHA256-Digest oder Minor/Patch
92:         if (dockerfileChanges.Count > 0 && versionFileChanges.Count == 0)
93:         {
94:             // Vereinfachte Prüfung: Der Aufrufer (AdoApiClient) liefert nur die Pfade.
95:             // Die tatsächliche Digest-Prüfung müsste über den Diff-Inhalt erfolgen.
