97:             return new FileAnalysis(true, "dockerfile_digest", Array.Empty<string>());
98:         }
99: 
100:         // Nur Versionsdateien: als patch/minor behandeln
101:         if (versionFileChanges.Count > 0 && dockerfileChanges.Count == 0)
102:             return new FileAnalysis(true, "patch", Array.Empty<string>());
103: 
104:         // Gemischt oder leer
105:         return changedFiles.Count == 0
106:             ? new FileAnalysis(false, "none", Array.Empty<string>())
107:             : new FileAnalysis(true, "patch", Array.Empty<string>());
108:     }
