135: 
136:         using var response = await httpClient.GetAsync(url, ct);
137:         if (!response.IsSuccessStatusCode)
138:             return new Dictionary<string, string>();
139: 
140:         var json = await response.Content.ReadAsStringAsync(ct);
141:         var doc = JsonDocument.Parse(json);
142: 
143:         var diffs = new Dictionary<string, string>();
144:         foreach (var change in doc.RootElement.GetProperty("changes").EnumerateArray())
145:         {
146:             if (!change.TryGetProperty("item", out var item) ||
147:                 !item.TryGetProperty("path", out var path))
148:             {
149:                 continue;
150:             }
151: 
152:             var filePath = path.GetString() ?? string.Empty;
153:             if (!IsDockerfile(filePath.ToLowerInvariant()))
154:                 continue;
155: 
156:             // Versuche, alten und neuen Inhalt zu extrahieren (je nach ADO Server Version verfügbar)
157:             var sb = new System.Text.StringBuilder();
158: 
159:             if (change.TryGetProperty("originalContent", out var original) &&
160:                 original.TryGetProperty("content", out var originalContent))
161:             {
162:                 sb.AppendLine("=== ALT ===");
163:                 sb.AppendLine(originalContent.GetString() ?? string.Empty);
164:             }
165: 
166:             if (change.TryGetProperty("newContent", out var neu) &&
167:                 neu.TryGetProperty("content", out var newContent))
168:             {
169:                 sb.AppendLine("=== NEU ===");
170:                 sb.AppendLine(newContent.GetString() ?? string.Empty);
171:             }
172: 
173:             if (sb.Length > 0)
174:                 diffs[filePath] = sb.ToString();
175:         }
176: 
177:         return diffs;
178:     }
