224:                 !string.Equals(oldDigest, newDigest, StringComparison.OrdinalIgnoreCase))
225:             {
226:                 return true;
227:             }
228: 
229:             // Wenn Tags unterschiedlich sind (aber gleiche Major) -> Minor/Patch, erlaubt
230:             if (!string.Equals(oldTag, newTag, StringComparison.OrdinalIgnoreCase))
231:                 return true;
232: 
233:             // Alles identisch -> keine Änderung
234:             return false;
235:         }
236: 
237:         return false;
238:     }
239: 
240:     private static int GetMajorVersion(string tag)
241:     {
242:         // Entferne führendes 'v' falls vorhanden
243:         var clean = tag.StartsWith("v", StringComparison.OrdinalIgnoreCase) ? tag[1..] : tag;
244:         var match = Regex.Match(clean, @"^(\d+)");
245:         return match.Success ? int.Parse(match.Groups[1].Value) : int.MaxValue;
246:     }
247: 
248:     private static bool IsMajorUpgrade(string title, IReadOnlyList<string> files)
249:     {
250:         var lowerTitle = title.ToLowerInvariant();
251:         if (lowerTitle.Contains("major") || lowerTitle.Contains("breaking"))
252:             return true;
253: 
254:         foreach (var file in files)
255:         {
256:             var lower = file.ToLowerInvariant();
257:             if (lower.Contains("major") || lower.Contains("breaking"))
258:                 return true;
259:         }
260: 
261:         return false;
262:     }
263: 
264:     private static bool IsDockerfile(string lowerPath) =>
265:         lowerPath.EndsWith("dockerfile") ||
266:         lowerPath.EndsWith(".dockerfile") ||
267:         lowerPath.Contains("dockerfile.");
268: 
269:     private static bool IsVersionFile(string lowerPath) =>
270:         lowerPath.EndsWith("csproj") ||
271:         lowerPath.EndsWith("nuspec") ||
272:         lowerPath.EndsWith("version.json") ||
273:         lowerPath.EndsWith("assemblyinfo.cs");
